def _merge_page(
    page_num: int,
    text_blocks: list[dict],
    tables: list[dict],
) -> dict[str, Any]:
    """
    Combine text_blocks and tables from both services into a single page dict.
    """
    return {
        "page_num":    page_num,
        "text_blocks": text_blocks,
        "tables":      tables,
    }
